public class PiePlot_initialise_TriageGen2Test {

    private PiePlot piePlot;
    private PieDataset mockDataset;
    private Graphics2D mockG2;
    private Rectangle2D mockPlotArea;
    private PlotRenderingInfo mockInfo;

    @Before
    public void setUp() {
        mockDataset = mock(PieDataset.class);
        piePlot = new PiePlot(mockDataset);
        mockG2 = mock(Graphics2D.class);
        mockPlotArea = new Rectangle2D.Double(0, 0, 100, 100);
        mockInfo = mock(PlotRenderingInfo.class);
    }

    @Test
    public void testInitialise() {
        // Arrange
        double expectedTotal = 100.0;
        double startAngle = 0.0;

        // Mock dataset behavior to satisfy DatasetUtilities.calculatePieDatasetTotal
        // Assuming DatasetUtilities calls getSeriesKey/getValue or similar, 
        // but since we can't easily mock the static utility without PowerMock,
        // we ensure the dataset returns values that sum up to a known total.
        // For JFreeChart, calculatePieDatasetTotal iterates through the dataset.
        when(mockDataset.getSeriesKey(0)).thenReturn("Key1");
        when(mockDataset.getSeriesValue(0)).thenReturn(expectedTotal);
        when(mockDataset.getSeriesCount()).thenReturn(1);

        piePlot.setStartAngle(startAngle);

        // Act
        PiePlotState result = piePlot.initialise(mockG2, mockPlotArea, piePlot, 0, mockInfo);

        // Assert
        assertNotNull("The returned state should not be null", result);
        assertEquals("Passes required should be 2", 2, result.getPassesRequired());
        assertEquals("Total should match the dataset sum", expectedTotal, result.getTotal(), 0.001);
        assertEquals("Latest angle should match start angle", startAngle, result.getLatestAngle(), 0.001);
    }

    @Test
    public void testInitialiseWithDifferentValues() {
        // Arrange
        double expectedTotal = 50.5;
        double startAngle = 90.0;

        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getSeriesValue(0)).thenReturn(expectedTotal);

        piePlot.setStartAngle(startAngle);

        // Act
        PiePlotState result = piePlot.initialise(mockG2, mockPlotArea, piePlot, 1, mockInfo);

        // Assert
        assertNotNull(result);
        assertEquals(2, result.getPassesRequired());
        assertEquals(expectedTotal, result.getTotal(), 0.001);
        assertEquals(startAngle, result.getLatestAngle(), 0.001);
    }
}
